import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size, int channels, int height, int width,
    int kernel_size, int stride, int padding, int dilation,
    int height_out, int width_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * channels * height_out * width_out;
    if (idx >= total) return;

    int wo = idx % width_out;
    int tmp = idx / width_out;
    int ho = tmp % height_out;
    tmp = tmp / height_out;
    int c = tmp % channels;
    int b = tmp / channels;

    float sum = 0.0f;
    int w_in = wo * stride - padding;
    if (w_in >= 0 && w_in < width) {
        const float* in_ptr = input + ((b * channels + c) * height) * width + w_in;
        const float* w_ptr = weight + c * kernel_size;
        #pragma unroll
        for (int kh = 0; kh < kernel_size; ++kh) {
            int h_in = ho * stride - padding + kh * dilation;
            if (h_in >= 0 && h_in < height) {
                sum += in_ptr[h_in * width] * w_ptr[kh];
            }
        }
    }
    if (bias != nullptr) {
        sum += bias[c];
    }
    output[((b * channels + c) * height_out + ho) * width_out + wo] = sum;
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation)
{
    input = input.contiguous();
    weight = weight.contiguous();

    int batch_size = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);
    int kernel_size = weight.size(2); // weight shape: (channels, 1, kernel_size, 1)

    int height_out = (height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int width_out = (width + 2 * padding - dilation * (1 - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, channels, height_out, width_out}, input.options());

    int total = batch_size * channels * height_out * width_out;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    const float* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }

    depthwise_conv2d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, channels, height, width,
        kernel_size, stride, padding, dilation,
        height_out, width_out
    );

    return output;
}
"""

cpp_source = r"""
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation);
"""

depthwise_conv2d_module = load_inline(
    name="depthwise_conv2d_module",
    cpp_sources=cpp_source,
    cuda_sources=source,
    functions=["depthwise_conv2d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a depthwise 2D convolution with a square input and an asymmetric kernel,
    using a custom CUDA kernel for the forward pass.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias

        # Weight shape matches nn.Conv2d depthwise weight: (in_channels, 1, kernel_size, 1)
        self.weight = nn.Parameter(torch.empty(in_channels, 1, kernel_size, 1))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(in_channels))
            fan_in = kernel_size
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

        self.conv_fn = depthwise_conv2d_module.depthwise_conv2d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias_tensor = self.bias if self.bias is not None else torch.tensor([], device=x.device, dtype=x.dtype)
        return self.conv_fn(
            x, self.weight, bias_tensor,
            self.stride, self.padding, self.dilation
        )


batch_size = 64
in_channels = 8
kernel_size = 3
width = 512
height = 512
stride = 1
padding = 0
dilation = 1


def get_inputs():
    x = torch.rand(batch_size, in_channels, height, width).cuda()
    return [x]


def get_init_inputs():
    return [in_channels, kernel_size, stride, padding, dilation]

